// Import the Verus standard library Prelude for Vec and other utilities
use vstd::prelude::*;

verus! {

    /// Returns the minimum element of a non-empty Vec<i8>.
    /// 
    /// Requirements:
    /// - `a.len() > 0`
    /// 
    /// Postconditions:
    /// - The result is less than or equal to every element of `a`.
    /// - The result is equal to some element of `a`.
    fn nanmin(a: Vec<i8>) -> (result: i8)
        requires
            a.len() > 0,
        ensures
            // result is ≤ every element in a
            forall |j: usize| j < a.len() ==> result <= a[j],
        ensures
            // result equals some element in a
            exists |j: usize| j < a.len() && result == a[j],
    {
        // Initialize index and current minimum
        let mut i: usize = 1;
        let mut min_val: i8 = a[0];

        // Loop over the rest of the elements
        while i < a.len()
            invariant
                // i stays within [0, a.len()]
                i <= a.len(),
            invariant
                // min_val is ≤ every element among the first i elements
                forall |j: usize| j < i ==> min_val <= a[j],
            invariant
                // min_val equals some element among the first i elements
                exists |j: usize| j < i && min_val == a[j],
            decreases
                // ensures termination
                a.len() - i
        {
            let v: i8 = a[i];
            if v < min_val {
                min_val = v;
            }
            i += 1;
        }

        // At this point, i == a.len(), so min_val is the min over all elements
        min_val
    }
}